INVITATION_TTL_DAYS = 7


def invite(account, actor, email):
    if actor.role != "OWNER":
        raise PermissionError("forbidden")
    if account.active_members() + account.pending_invitations() >= account.plan.seat_limit:
        raise ValueError("No seats available")
    return account.create_invitation(email, ttl_days=INVITATION_TTL_DAYS)

