def test_owner_can_invite(account, owner):
    assert invite(account, owner, "a@example.com").status == "PENDING"


def test_invite_rejected_when_seats_full(full_account, owner):
    with pytest.raises(ValueError):
        invite(full_account, owner, "b@example.com")


